// Server-only: link previews (WhatsApp, Instagram, Facebook…) built from the cards
// generated by scripts/og-images.mjs into /public/og.
import type { Metadata } from "next";
import { settings } from "@/data/settings";
import { publicFileExists } from "./assets.server";

export const SITE_TITLE = "Mery Naje — Prêt-à-porter féminin à Casablanca";
export const SITE_DESCRIPTION =
  "Robes, ensembles et manteaux à Casablanca. Livraison partout au Maroc, paiement à la livraison : commandez en quelques clics sur WhatsApp.";

const SITE_CARD = "/og/site.jpg";

/** Open Graph + Twitter tags for a page. `card` falls back to the site card if missing. */
export function shareMetadata({
  title,
  description,
  card,
}: {
  title: string;
  description: string;
  card?: string;
}): Pick<Metadata, "openGraph" | "twitter"> {
  const image = card && publicFileExists(card) ? card : SITE_CARD;
  const images = [{ url: image, width: 1200, height: 630, alt: title, type: "image/jpeg" }];
  return {
    openGraph: { type: "website", locale: "fr_MA", siteName: settings.storeName, title, description, images },
    twitter: { card: "summary_large_image", title, description, images: [image] },
  };
}
